    static BlockState surfaceState(int theme, int slot) {
        return switch (theme) {
            case 0 -> (slot == 30 ? ModBlocks.WIND_ASHLAR : ModBlocks.WIND_CARVED_FRIEZE).get().defaultBlockState();
            case 2 -> (slot == 30 ? ModBlocks.WHISPERING_PANELLED_PLANKS : ModBlocks.WHISPERING_CARVED_PANELS).get().defaultBlockState();
            case 4 -> (slot == 30 ? ModBlocks.FOLDED_SLATE_TILES : ModBlocks.FOLDED_SLATE_RELIEF).get().defaultBlockState();
            case 6 -> (slot == 30 ? ModBlocks.FOLDED_SLATE_TILES : ModBlocks.FOLDED_SLATE_RELIEF).get().defaultBlockState();
            case 7 -> (slot == 30 ? ModBlocks.WHISPERING_PANELLED_PLANKS : ModBlocks.WHISPERING_CARVED_PANELS).get().defaultBlockState();
            case 8 -> (slot == 30 ? ModBlocks.WHISPERING_PANELLED_PLANKS : ModBlocks.WHISPERING_CARVED_PANELS).get().defaultBlockState();
            default -> throw new IllegalArgumentException("Unknown surface theme: " + theme);
        };
    }

    static BlockState compositionState(int theme) {
        return switch (theme) {
            case 0 -> ModBlocks.WIND_ASHLAR.get().defaultBlockState();
            case 1 -> ModBlocks.IVORY_REEF_ASHLAR.get().defaultBlockState();
            case 2 -> ModBlocks.WHISPERING_PANELLED_PLANKS.get().defaultBlockState();
            case 3 -> ModBlocks.ASHEN_BELLSTONE_BRICKS.get().defaultBlockState();
            case 4 -> ModBlocks.FOLDED_SLATE_TILES.get().defaultBlockState();
            case 5 -> ModBlocks.ECHO_STRATA_BRICKS.get().defaultBlockState();
            case 6 -> ModBlocks.GRAVITY_SHALE_BRICKS.get().defaultBlockState();
            case 7 -> ModBlocks.WHISPERING_PANELLED_PLANKS.get().defaultBlockState();
            case 8 -> ModBlocks.TARRED_SHIP_PLANKS.get().defaultBlockState();
            default -> throw new IllegalArgumentException("Unknown composition theme: " + theme);
        };
    }

    record SlabContact(int x, int y, int z, Block slab, BlockState state) {}
    // 按布局解析方块引用；注册未完成的失败不能留下缓存，后续调用必须能重试。
    private static final Map<String, List<SlabContact>> SLAB_CONTACTS = new java.util.concurrent.ConcurrentHashMap<>();
    static List<SlabContact> slabContacts(String id) {
        return switch (id) {
            case "cliff_bridge",
                 "crystal_song_hall",
                 "crystal_song_shrine",
                 "echo_temple_archive",
                 "echo_temple_archive_e",
                 "echo_temple_treasure",
                 "gravity_crown_observatory",
                 "illusion_wall_chamber",
                 "inverted_chasm_bridge",
                 "memory_pillar_courtyard",
                 "mirror_lake_cache",
                 "resonance_foundry",
                 "rune_puzzle_room",
                 "shattered_codex_vault",
                 "silent_altar",
                 "sky_observatory",
                 "submerged_record_room",
                 "suspended_survey_station",
                 "tide_buoy_array",
                 "underground_greenhouse",
                 "weightless_orrery_court",
                 "wind_eroded_tower" -> SLAB_CONTACTS.computeIfAbsent(id, StructureExteriorLayouts::createSlabContacts);
            default -> List.of();
        };
    }

